events.Step:
// Đuổi theo người chơi
var _dir = point_direction(x, y, obj_player.x, obj_player.y);
x += lengthdir_x(spd, _dir);
y += lengthdir_y(spd, _dir);

instance_create_depth(x, y, -100, obj_bullet_enemy);

events.Collision_obj_enemy:
// Va chạm với kẻ địch
hp -= 10;
with (obj_enemy) {
    instance_destroy();
}

events.Collision_obj_wall:
// Va chạm với tường
x = xprevious;
y = yprevious;

events.Create:
// Khởi tạo nhân vật
hp = 100;
spd = 4;
score = 0;

events.Step:
// Di chuyển
x += spd * keyboard_check(vk_right);
y += spd * keyboard_check(vk_down);

if (keyboard_check_pressed(vk_space)) {
    instance_create_layer(x, y, "Instances", obj_bullet);
}

if (place_meeting(x, y, obj_wall)) {
    x = xprevious;
    y = yprevious;
}

obj_score_manager.score = score;

events.Draw_GUI:
// Hiển thị điểm
draw_set_font(fnt_score);
draw_text(10, 10, "Score: " + string(score));
